<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Rest;use Acorn\SafetyHealthcheck\Assessment\CompletionService;use WP_REST_Request;use WP_REST_Response;use Throwable;final class CompletionController{public function register():void{register_rest_route('acorn-healthcheck/v1','/assessments/(?P<token>[A-Za-z0-9_-]+)/complete',['methods'=>'POST','callback'=>[$this,'complete'],'permission_callback'=>'__return_true']);}public function complete(WP_REST_Request$r):WP_REST_Response{try{return new WP_REST_Response((new CompletionService)->complete($r['token'],$r->get_json_params()),200);}catch(Throwable$e){return new WP_REST_Response(['code'=>'completion_error','message'=>$e->getMessage()],400);}}}
